import type { LazySchema } from "entry-reader-owner-lab";
export type FinishReason = "stop" | "length";
export type Chunk = { type: "start" } | { type: "finish"; finishReason?: FinishReason };
/** The dependency's generic over entry types: shapes hoisted under it read `FinishReason`. */
export declare const chunkSchema: LazySchema<Chunk>;
